import { CustomBlobDocument, StudioProApi } from "@mendix/extensions-api";
import { ILogObj, Logger } from "tslog";
import {
    CONSTANT_DOCUMENT_TYPE,
    CUSTOM_BLOB_DOCUMENT_TYPE,
    ENTITY_DOCUMENT_TYPE,
    MICROFLOW_DOCUMENT_TYPE,
    MODULE_DOCUMENT_TYPE,
} from "../constants/studioPro";
import {
    agentDocumentTypeId,
    consumedMCPServiceDocumentTypeId,
    knowledgeBaseDocumentTypeId,
    modelDocumentTypeId,
} from ".";
import { Agent } from "../types/agent";
import { ConsumedMCPService } from "../types/consumedMCPService";
import { Knowledgebase } from "../types/knowledgebase/knowledgebase";
import { MxCloudGenAIKnowledgebaseFields } from "../types/knowledgebase/mxCloudGenAIKnowledgebase";
import { Model } from "../types/model/model";
import { MxCloudGenAIModelFields } from "../types/model/mxCloudGenAIModel";
import { ModelDocument } from "../types/modelDocument";

export type RenameInfo = {
    oldName: { qualifiedName: string };
    newName: { qualifiedName: string };
    documentType: string;
};

/**
 * Sets up an event listener to handle renamed elements in the Mendix project.
 * Updates dependencies in agents, models, knowledgebases, and consumed MCP services.
 */
export async function handleRenamedElements(studioPro: StudioProApi, logger: Logger<ILogObj>): Promise<void> {
    try {
        studioPro.app.projectChanges.addEventListener("elementsRenamed", async ({ elements }) => {
            await updateAgentDependencies(studioPro, elements);
            await updateModelDependencies(studioPro, elements);
            await updateConsumedMCPServiceDependencies(studioPro, elements);
            await updateKnowledgeBaseDependencies(studioPro, elements);
        });
    } catch (error) {
        logger.error("Failed to set up elementsRenamed event listener", { error });
    }
}

/**
 * Updates a dependency's qualified name and saves the document.
 */
function renameDependency(
    dependency: ModelDocument,
    newName: string,
    studioPro: StudioProApi,
    blobDocumentId: string,
    contents: object
): void {
    // Dependency is a nested object of type ModelDocument that is part of contents (of the custom document)
    // and therefore the reference in contents is also updated with the new name.
    dependency.qualifiedName = newName;

    studioPro.app.model.customBlobDocuments.updateDocumentContent(blobDocumentId, contents);
}

/**
 * Checks if a dependency was renamed and returns the new qualified name.
 * Handles both element renames and module renames that affect qualified names.
 * @returns The new qualified name if renamed, undefined otherwise
 */
function checkDependencyRenamed(
    dependency: ModelDocument,
    renames: RenameInfo[],
    expectedDocumentTypes?: string[]
): string | undefined {
    const moduleRenames = renames.find((r) => r.documentType === MODULE_DOCUMENT_TYPE);

    if (moduleRenames) {
        const [moduleName, documentName] = dependency.qualifiedName.split(".");
        if (moduleRenames.oldName.qualifiedName === moduleName) {
            return `${moduleRenames.newName.qualifiedName}.${documentName}`;
        }
    }

    const rename = renames.find((rename) => {
        if (rename.oldName.qualifiedName !== dependency.qualifiedName) {
            return false;
        }

        // If expected types are specified, check if the rename matches
        if (expectedDocumentTypes) {
            return expectedDocumentTypes.includes(rename.documentType);
        }

        return true;
    });

    return rename?.newName.qualifiedName;
}

/**
 * Checks if a model document dependency was renamed and updates it if necessary.
 */
function checkAndRenameDependency(
    studioPro: StudioProApi,
    customBlobDocument: CustomBlobDocument,
    modelDocument: ModelDocument,
    elements: RenameInfo[],
    expectedDocumentTypes: string[]
) {
    const newName = checkDependencyRenamed(modelDocument, elements, expectedDocumentTypes);
    if (newName) {
        renameDependency(modelDocument, newName, studioPro, customBlobDocument.$ID, customBlobDocument.contents);
    }
}

/**
 * Updates dependencies in all agent documents (model, entity, and tool references).
 */
async function updateAgentDependencies(studioPro: StudioProApi, elements: RenameInfo[]): Promise<void> {
    const agentDocuments = await studioPro.app.model.customBlobDocuments.getDocumentsOfType(agentDocumentTypeId);

    for (const doc of agentDocuments) {
        const d = await studioPro.app.model.customBlobDocuments.getDocumentById<Agent>(doc.id);

        if ("document" in d && d.document) {
            if (d.document.contents.model) {
                checkAndRenameDependency(studioPro, d.document, d.document.contents.model, elements, [
                    CUSTOM_BLOB_DOCUMENT_TYPE,
                ]);
            }

            if (d.document.contents.entity) {
                checkAndRenameDependency(studioPro, d.document, d.document.contents.entity, elements, [
                    ENTITY_DOCUMENT_TYPE,
                ]);
            }

            if (d.document.contents.tools) {
                for (const tool of d.document.contents.tools) {
                    checkAndRenameDependency(studioPro, d.document, tool.document, elements, [
                        MICROFLOW_DOCUMENT_TYPE,
                        CUSTOM_BLOB_DOCUMENT_TYPE,
                    ]);
                }
            }

            if (d.document.contents.knowledgebaseTools) {
                for (const knowledgebaseTool of d.document.contents.knowledgebaseTools) {
                    checkAndRenameDependency(studioPro, d.document, knowledgebaseTool.document, elements, [
                        CUSTOM_BLOB_DOCUMENT_TYPE,
                    ]);
                }
            }
        }
    }
}

/**
 * Updates MxCloudGenAI key references in model documents.
 */
async function updateModelDependencies(studioPro: StudioProApi, elements: RenameInfo[]): Promise<void> {
    const modelDocuments = await studioPro.app.model.customBlobDocuments.getDocumentsOfType(modelDocumentTypeId);

    for (const doc of modelDocuments) {
        const d = await studioPro.app.model.customBlobDocuments.getDocumentById<Model>(doc.id);

        if ("document" in d && d.document) {
            if (d.document.contents.provider === "MxCloudGenAI") {
                const providerFields = d.document.contents.providerFields as MxCloudGenAIModelFields;
                if (!providerFields.key) {
                    continue;
                }
                checkAndRenameDependency(studioPro, d.document, providerFields.key, elements, [CONSTANT_DOCUMENT_TYPE]);
            }
        }
    }
}

/**
 * Updates MxCloudGenAI key references in knowledgebase documents.
 */
async function updateKnowledgeBaseDependencies(studioPro: StudioProApi, elements: RenameInfo[]): Promise<void> {
    const knowledgeBaseDocuments =
        await studioPro.app.model.customBlobDocuments.getDocumentsOfType(knowledgeBaseDocumentTypeId);

    for (const doc of knowledgeBaseDocuments) {
        const d = await studioPro.app.model.customBlobDocuments.getDocumentById<Knowledgebase>(doc.id);

        if ("document" in d && d.document) {
            if (d.document.contents.provider === "MxCloudGenAI") {
                const providerFields = d.document.contents.providerFields as MxCloudGenAIKnowledgebaseFields;
                if (!providerFields.key) {
                    continue;
                }
                checkAndRenameDependency(studioPro, d.document, providerFields.key, elements, [CONSTANT_DOCUMENT_TYPE]);
            }
        }
    }
}

/**
 * Updates endpoint references in consumed MCP service documents.
 */
async function updateConsumedMCPServiceDependencies(studioPro: StudioProApi, elements: RenameInfo[]): Promise<void> {
    const modelDocuments = await studioPro.app.model.customBlobDocuments.getDocumentsOfType(
        consumedMCPServiceDocumentTypeId
    );

    for (const doc of modelDocuments) {
        const d = await studioPro.app.model.customBlobDocuments.getDocumentById<ConsumedMCPService>(doc.id);

        if ("document" in d && d.document) {
            if (d.document.contents.endpoint) {
                checkAndRenameDependency(studioPro, d.document, d.document.contents.endpoint, elements, [
                    CONSTANT_DOCUMENT_TYPE,
                ]);
            }
        }
    }
}
