import { ConsistencyError, Microflows, StudioProApiHeadless } from "@mendix/extensions-api";
import { ToolChoices } from "@src/constants/tool";
import {
    AGENT_RESERVED_ERROR_CODES,
    ENTITY_MISSING_VARIABLES_ERROR_CODE,
    ENTITY_NOT_FOUND_ERROR_CODE,
    ENTITY_REQUIRED_ERROR_CODE,
    KNOWLEDGEBASE_EXCLUDED_ERROR_CODE,
    KNOWLEDGEBASE_NOT_FOUND_ERROR_CODE,
    MODEL_EXCLUDED_ERROR_CODE,
    MODEL_NOT_FOUND_ERROR_CODE,
    MODEL_REQUIRED_ERROR_CODE,
    TOOL_EXCLUDED_ERROR_CODE,
    TOOL_MICROFLOW_INVALID_PARAMETER_TYPE_ERROR_CODE,
    TOOL_MICROFLOW_RETURN_TYPE_ERROR_CODE,
    TOOL_NOT_FOUND_ERROR_CODE,
    TOOLCHOICE_TOOL_NOT_ACTIVE_ERROR_CODE,
    TOOLCHOICE_TOOL_NOT_FOUND_ERROR_CODE,
    TOOLCHOICE_TOOL_REQUIRED_ERROR_CODE,
    USER_PROMPT_REQUIRED_ERROR_CODE,
    USAGE_TYPE_REQUIRED_ERROR_CODE,
} from "../../constants/consistencyCodes";
import { Agent } from "../../types/agent";
import { ConsistencyCheckResult } from "../../types/generic";
import { Tool } from "../../types/tool";
import { getCustomBlobDocumentById } from "../../utils/customBlobDocumentUtils";
import { getEntity } from "../../utils/domainModelUtils";
import { getMicroflowsByIds } from "../../utils/microflowUtils";
import { getToolById, getToolLabel, isMicroflowTool, validateMicroflowParameterTypes } from "../../utils/toolUtils";
import { UsageTypes } from "@src/constants/agent";

export const registerAgentConsistencyChecks = (studioPro: StudioProApiHeadless) => ({
    check: async (document: Agent) => {
        const modelResult = await checkModel(studioPro, document);
        const entityResult = await checkEntity(studioPro, document);
        const userPromptResult = checkUserPrompt(document);
        const usageTypeResult = checkUsageType(document);
        const toolChoiceResult = checkToolChoice(document);
        const toolsResult = await checkTools(studioPro, document);
        const knowledgebaseResult = await checkKnowledgebaseTools(studioPro, document);

        return {
            errors: [
                ...modelResult.errors,
                ...entityResult.errors,
                ...userPromptResult.errors,
                ...usageTypeResult.errors,
                ...toolChoiceResult.errors,
                ...toolsResult.errors,
                ...knowledgebaseResult.errors,
            ],
            dependentElementIds: [
                ...modelResult.dependentElementIds,
                ...entityResult.dependentElementIds,
                ...userPromptResult.dependentElementIds,
                ...toolChoiceResult.dependentElementIds,
                ...toolsResult.dependentElementIds,
                ...knowledgebaseResult.dependentElementIds,
            ],
        };
    },
    reservedErrorCodes: AGENT_RESERVED_ERROR_CODES,
});

async function checkModel(studioPro: StudioProApiHeadless, document: Agent): Promise<ConsistencyCheckResult> {
    const errors: ConsistencyError[] = [];
    const dependentElementIds: string[] = [];

    if (!document.model) {
        errors.push({
            elementText: "Model",
            errorCode: MODEL_REQUIRED_ERROR_CODE,
            errorDescription: "Model is required for an agent.",
            severity: "error",
        });
        return { errors, dependentElementIds };
    }

    dependentElementIds.push(document.model.documentId);

    const model = await getCustomBlobDocumentById(studioPro, document.model);

    if (!model) {
        errors.push({
            elementText: "Model",
            errorCode: MODEL_NOT_FOUND_ERROR_CODE,
            errorDescription: `Model ${document.model.qualifiedName} could not be found. Please make sure it exists and is correctly referenced.`,
            severity: "error",
        });
    } else if (model.excluded) {
        errors.push({
            elementText: "Model",
            errorCode: MODEL_EXCLUDED_ERROR_CODE,
            errorDescription: `Model ${document.model.qualifiedName} is excluded from the project and cannot be used.`,
            severity: "error",
        });
    }

    return { errors, dependentElementIds };
}

async function checkEntity(studioPro: StudioProApiHeadless, document: Agent): Promise<ConsistencyCheckResult> {
    const errors: ConsistencyError[] = [];
    const dependentElementIds: string[] = [];

    if (!document.entity) {
        if (document.variables.length > 0) {
            errors.push({
                elementText: "Context entity",
                errorCode: ENTITY_REQUIRED_ERROR_CODE,
                errorDescription: "Context entity is required for an agent when using variables.",
                severity: "error",
            });
        }

        return { errors, dependentElementIds: [] };
    }

    dependentElementIds.push(document.entity.documentId);

    const entity = await getEntity(studioPro, document.entity.qualifiedName);
    const missingVariables = document.variables.filter((v) => !v.isAttributeInEntity).map((v) => v.key);

    if (!entity) {
        errors.push({
            elementText: "Context entity",
            errorCode: ENTITY_NOT_FOUND_ERROR_CODE,
            errorDescription: `Context entity ${document.entity.qualifiedName} could not be found. Please make sure it exists and is correctly referenced.`,
            severity: "error",
        });
    } else if (missingVariables.length > 0) {
        errors.push({
            elementText: "Context entity",
            errorCode: ENTITY_MISSING_VARIABLES_ERROR_CODE,
            errorDescription: `Variable${missingVariables.length > 1 ? "s" : ""} ${missingVariables.join(", ")} could not be found in context entity ${document.entity.qualifiedName}.`,
            severity: "warning",
        });
    }

    return { errors, dependentElementIds };
}

function checkUserPrompt(document: Agent): ConsistencyCheckResult {
    const errors: ConsistencyError[] = [];

    if (document.usageType === UsageTypes.Task && !document.userPrompt) {
        errors.push({
            elementText: "User prompt",
            errorCode: USER_PROMPT_REQUIRED_ERROR_CODE,
            errorDescription: "User prompt is required for an agent.",
            severity: "error",
        });
    }

    return { errors, dependentElementIds: [] };
}

function checkUsageType(document: Agent): ConsistencyCheckResult {
    const errors: ConsistencyError[] = [];

    if (!document.usageType) {
        errors.push({
            elementText: "Agent type",
            errorCode: USAGE_TYPE_REQUIRED_ERROR_CODE,
            errorDescription: "Agent type is required for an agent.",
            severity: "error",
        });
    }

    return { errors, dependentElementIds: [] };
}

function checkToolChoice(document: Agent): ConsistencyCheckResult {
    const errors: ConsistencyError[] = [];

    if (document.toolChoice !== ToolChoices.Tool) {
        return { errors, dependentElementIds: [] };
    }

    if (!document.toolChoiceToolName) {
        errors.push({
            elementText: "Tool choice",
            errorCode: TOOLCHOICE_TOOL_REQUIRED_ERROR_CODE,
            errorDescription: "A specific tool must be selected when tool choice is set to 'Tool'.",
            severity: "error",
        });
    } else {
        // Check if the selected tool exists in the tools array
        const selectedTool = document.tools.find((tool) => tool.name === document.toolChoiceToolName);

        if (!selectedTool) {
            errors.push({
                elementText: "Tool choice",
                errorCode: TOOLCHOICE_TOOL_NOT_FOUND_ERROR_CODE,
                errorDescription: `Tool '${document.toolChoiceToolName}' is not in the agent's tools list. Please update your tool selection or change the tool choice.`,
                severity: "error",
            });
        } else if (!selectedTool.enabled) {
            // Check if the selected tool is enabled
            errors.push({
                elementText: "Tool choice",
                errorCode: TOOLCHOICE_TOOL_NOT_ACTIVE_ERROR_CODE,
                errorDescription: `Tool '${document.toolChoiceToolName}' is not active. Please activate it, or select a different tool.`,
                severity: "error",
            });
        }
    }

    return { errors, dependentElementIds: [] };
}

async function checkTools(studioPro: StudioProApiHeadless, document: Agent): Promise<ConsistencyCheckResult> {
    const errors: ConsistencyError[] = [];
    const dependentElementIds: string[] = [];

    const microflowDocuments = document.tools
        .filter((t) => t.enabled && t.toolType === "Microflow")
        .map((t) => t.document);
    const microflowsMap = await getMicroflowsByIds(studioPro, microflowDocuments);

    for (const agentTool of document.tools) {
        if (!agentTool.enabled) {
            continue; // skip validation for disabled tools
        }

        dependentElementIds.push(agentTool.document.documentId);

        const tool =
            agentTool.toolType === "Microflow"
                ? microflowsMap.get(agentTool.document.documentId)
                : await getToolById(studioPro, agentTool.toolType, agentTool.document);
        const toolLabel = getToolLabel(agentTool.toolType);

        if (!tool) {
            errors.push({
                elementText: "Tools",
                errorCode: TOOL_NOT_FOUND_ERROR_CODE,
                errorDescription: `${toolLabel} ${agentTool.document.qualifiedName} could not be found. Please make sure it exists and is correctly referenced.`,
                severity: "error",
            });
        } else if (tool.excluded) {
            errors.push({
                elementText: "Tools",
                errorCode: TOOL_EXCLUDED_ERROR_CODE,
                errorDescription: `${toolLabel} ${agentTool.document.qualifiedName} is excluded from the project and cannot be used.`,
                severity: "error",
            });
        } else if (isMicroflowTool(tool)) {
            const { errors: microflowErrors } = checkMicroflowTool(tool, agentTool);
            errors.push(...microflowErrors);
        }
    }

    return { errors, dependentElementIds };
}

async function checkKnowledgebaseTools(
    studioPro: StudioProApiHeadless,
    document: Agent
): Promise<ConsistencyCheckResult> {
    const errors: ConsistencyError[] = [];
    const dependentElementIds: string[] = [];
    if (document.knowledgebaseTools) {
        for (const knowledgebaseTool of document.knowledgebaseTools) {
            if (!knowledgebaseTool.enabled) {
                continue; // skip validation for disabled knowledge base tools
            }

            dependentElementIds.push(knowledgebaseTool.document.documentId);

            const knowledgebase = await getCustomBlobDocumentById(studioPro, knowledgebaseTool.document);

            if (!knowledgebase) {
                errors.push({
                    elementText: "Knowledge bases",
                    errorCode: KNOWLEDGEBASE_NOT_FOUND_ERROR_CODE,
                    errorDescription: `Knowledge base ${knowledgebaseTool.document.qualifiedName} could not be found. Please make sure it exists and is correctly referenced.`,
                    severity: "error",
                });
            } else if (knowledgebase.excluded) {
                errors.push({
                    elementText: "Knowledge bases",
                    errorCode: KNOWLEDGEBASE_EXCLUDED_ERROR_CODE,
                    errorDescription: `Knowledge base ${knowledgebaseTool.document.qualifiedName} is excluded from the project and cannot be used.`,
                    severity: "error",
                });
            }
        }
    }

    return { errors, dependentElementIds };
}

function checkMicroflowTool(tool: Microflows.Microflow, agentTool: Tool): ConsistencyCheckResult {
    const errors: ConsistencyError[] = [];

    if (tool.microflowReturnType.$Type !== "DataTypes$StringType") {
        errors.push({
            elementText: "Tools",
            errorCode: TOOL_MICROFLOW_RETURN_TYPE_ERROR_CODE,
            errorDescription: `Microflow ${agentTool.document.qualifiedName} must return a String.`,
            severity: "error",
        });
    }

    if (validateMicroflowParameterTypes(tool)) {
        errors.push({
            elementText: "Tools",
            errorCode: TOOL_MICROFLOW_INVALID_PARAMETER_TYPE_ERROR_CODE,
            errorDescription: `Microflow ${agentTool.document.qualifiedName} has invalid parameter types. Only primitive types and GenAICommons.Request or GenAICommons.Tool objects are supported.`,
            severity: "error",
        });
    }

    return { errors, dependentElementIds: [] };
}
