import { Microflows, StudioProApi, StudioProApiHeadless } from "@mendix/extensions-api";
import { ModelDocument } from "../types/modelDocument";

export const handleShowMicroflow = async (studioPro: StudioProApi, modelDocument: ModelDocument): Promise<void> => {
    const microflow = await getMicroflowById(studioPro, modelDocument);

    if (!microflow) {
        const errorMessage = "Could not find microflow.";
        const errorDetails =
            "This microflow might have been deleted or renamed. Please update the tool microflow selection.";
        return await studioPro.ui.messageBoxes.show("error", errorMessage, errorDetails);
    }

    await studioPro.ui.editors.editDocument(microflow.$ID);
};

export const getMicroflowById = async (
    studioPro: StudioProApiHeadless,
    modelDocument: ModelDocument
): Promise<Microflows.Microflow | undefined> => {
    if (!modelDocument.documentId) {
        return undefined;
    }

    try {
        const microflows = await studioPro.app.model.microflows.loadAll((m) => m.$ID === modelDocument.documentId);
        if (microflows[0] && microflows[0].name === modelDocument.qualifiedName.split(".")[1]) {
            return microflows[0];
        }
        return undefined;
    } catch {
        return undefined;
    }
};

export const getMicroflowsByIds = async (
    studioPro: StudioProApiHeadless,
    modelDocuments: ModelDocument[]
): Promise<Map<string, Microflows.Microflow>> => {
    const result = new Map<string, Microflows.Microflow>();

    if (modelDocuments.length === 0) {
        return result;
    }

    const documentsById = new Map(modelDocuments.map((doc) => [doc.documentId, doc]));
    const documentIds = new Set(documentsById.keys());

    try {
        const microflows = await studioPro.app.model.microflows.loadAll(
            (m) => documentIds.has(m.$ID),
            documentIds.size
        );

        for (const microflow of microflows) {
            const matchingDoc = documentsById.get(microflow.$ID);

            if (matchingDoc && microflow.name === matchingDoc.qualifiedName.split(".")[1]) {
                result.set(matchingDoc.documentId, microflow);
            }
        }
    } catch {
        // return partial results on failure
    }

    return result;
};
