import { agentDocumentTypeId } from "@src/main";
import { DEFAULT_MCP_PROTOCOL_VERSION } from "../constants/mcp";
import { Agent, AgentDocument } from "../types/agent";
import { ConsumedMCPService } from "../types/consumedMCPService";
import { Knowledgebase, Provider as KnowledgebaseProvider } from "../types/knowledgebase/knowledgebase";
import { MxCloudGenAIKnowledgebaseFields } from "../types/knowledgebase/mxCloudGenAIKnowledgebase";
import { Model, Provider as ModelProvider, ModelType } from "../types/model/model";
import { MxCloudGenAIModelFields } from "../types/model/mxCloudGenAIModel";

export function createNewAgentDocument(): AgentDocument {
    return {
        $ID: "",
        name: "",
        excluded: false,
        documentType: agentDocumentTypeId,
        contents: createNewAgent(),
    };
}

export function createNewAgent(): Agent {
    return {
        description: "",
        systemPrompt: "",
        userPrompt: "",
        usageType: "Task",
        variables: [],
        tools: [],
        knowledgebaseTools: [],
    };
}

export function createNewModel(): Model {
    return {
        type: "" as ModelType,
        name: "",
        displayName: "",
        provider: "MxCloudGenAI" as ModelProvider, // Preselect MxCloudGenAI as default provider
        providerFields: createNewMxCloudGenAIModelFields(),
    };
}

export const createNewMxCloudGenAIModelFields = (): MxCloudGenAIModelFields => {
    return {
        environment: "",
        deepLinkURL: "",
        keyId: "",
        keyName: "",
        resourceName: "",
    };
};

export function createNewConsumedMCPService(): ConsumedMCPService {
    return {
        protocolVersion: DEFAULT_MCP_PROTOCOL_VERSION,
    };
}

export function createNewKnowledgebase(): Knowledgebase {
    return {
        name: "",
        provider: "MxCloudGenAI" as KnowledgebaseProvider, // Preselect MxCloudGenAI as default provider
        providerFields: createNewMxCloudGenAIKnowledgebaseFields(),
    };
}

export const createNewMxCloudGenAIKnowledgebaseFields = (): MxCloudGenAIKnowledgebaseFields => {
    return {
        environment: "",
        deepLinkURL: "",
        keyId: "",
        keyName: "",
        modelDisplayName: "",
        modelName: "",
    };
};
